import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("Successful sign-in returns a session", { tag: "@AUTH-01" }, async ({ request }) => {
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });

  expect(response.status(), await response.text()).toBe(200);

  const body = await response.json();
  expect(body.access_token, JSON.stringify(body)).toBeTruthy();

  const cookie = response
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, JSON.stringify(response.headersArray())).toBeDefined();
  expect(cookie?.value.toLowerCase()).toContain("httponly");
});
